import math, logging
from . import bus
REPORT_TIME = 0.3
MAX_INVALID_COUNT = 3

class SensorBase:

    def __init__(self, config, chip_type, config_cmd=None, spi_mode=1):
        self.printer = config.get_printer()
        self.chip_type = chip_type
        self._callback = None
        self.min_sample_value = self.max_sample_value = 0
        self._report_clock = 0
        self.spi = bus.MCU_SPI_from_config(config,
          spi_mode, pin_option="sensor_pin", default_speed=4000000)
        if config_cmd is not None:
            self.spi.spi_send(config_cmd)
        self.mcu = mcu = self.spi.get_mcu()
        self.oid = oid = mcu.create_oid()
        mcu.register_response(self._handle_spi_response, "thermocouple_result", oid)
        mcu.register_config_callback(self._build_config)

    def setup_minmax(self, min_temp, max_temp):
        adc_range = [self.calc_adc(min_temp), self.calc_adc(max_temp)]
        self.min_sample_value = min(adc_range)
        self.max_sample_value = max(adc_range)

    def setup_callback(self, cb):
        self._callback = cb

    def get_report_time_delta(self):
        return REPORT_TIME

    def _build_config(self):
        self.mcu.add_config_cmd("config_thermocouple oid=%u spi_oid=%u thermocouple_type=%s" % (
         self.oid, self.spi.get_oid(), self.chip_type))
        clock = self.mcu.get_query_slot(self.oid)
        self._report_clock = self.mcu.seconds_to_clock(REPORT_TIME)
        self.mcu.add_config_cmd(("query_thermocouple oid=%u clock=%u rest_ticks=%u min_value=%u max_value=%u max_invalid_count=%u" % (
         self.oid, clock, self._report_clock,
         self.min_sample_value, self.max_sample_value,
         MAX_INVALID_COUNT)),
          is_init=True)

    def _handle_spi_response(self, params):
        if params["fault"]:
            self.handle_fault(params["value"], params["fault"])
            return
        temp = self.calc_temp(params["value"])
        next_clock = self.mcu.clock32_to_clock64(params["next_clock"])
        last_read_clock = next_clock - self._report_clock
        last_read_time = self.mcu.clock_to_print_time(last_read_clock)
        self._callback(last_read_time, temp)

    def report_fault(self, msg):
        logging.warning(msg)


MAX31856_CR0_REG = 0
MAX31856_CR0_AUTOCONVERT = 128
MAX31856_CR0_1SHOT = 64
MAX31856_CR0_OCFAULT1 = 32
MAX31856_CR0_OCFAULT0 = 16
MAX31856_CR0_CJ = 8
MAX31856_CR0_FAULT = 4
MAX31856_CR0_FAULTCLR = 2
MAX31856_CR0_FILT50HZ = 1
MAX31856_CR0_FILT60HZ = 0
MAX31856_CR1_REG = 1
MAX31856_CR1_AVGSEL1 = 0
MAX31856_CR1_AVGSEL2 = 16
MAX31856_CR1_AVGSEL4 = 32
MAX31856_CR1_AVGSEL8 = 48
MAX31856_CR1_AVGSEL16 = 112
MAX31856_MASK_REG = 2
MAX31856_MASK_COLD_JUNCTION_HIGH_FAULT = 32
MAX31856_MASK_COLD_JUNCTION_LOW_FAULT = 16
MAX31856_MASK_THERMOCOUPLE_HIGH_FAULT = 8
MAX31856_MASK_THERMOCOUPLE_LOW_FAULT = 4
MAX31856_MASK_VOLTAGE_UNDER_OVER_FAULT = 2
MAX31856_MASK_THERMOCOUPLE_OPEN_FAULT = 1
MAX31856_CJHF_REG = 3
MAX31856_CJLF_REG = 4
MAX31856_LTHFTH_REG = 5
MAX31856_LTHFTL_REG = 6
MAX31856_LTLFTH_REG = 7
MAX31856_LTLFTL_REG = 8
MAX31856_CJTO_REG = 9
MAX31856_CJTH_REG = 10
MAX31856_CJTL_REG = 11
MAX31856_LTCBH_REG = 12
MAX31856_LTCBM_REG = 13
MAX31856_LTCBL_REG = 14
MAX31856_SR_REG = 15
MAX31856_FAULT_CJRANGE = 128
MAX31856_FAULT_TCRANGE = 64
MAX31856_FAULT_CJHIGH = 32
MAX31856_FAULT_CJLOW = 16
MAX31856_FAULT_TCHIGH = 8
MAX31856_FAULT_TCLOW = 4
MAX31856_FAULT_OVUV = 2
MAX31856_FAULT_OPEN = 1
MAX31856_SCALE = 5
MAX31856_MULT = 0.0078125

class MAX31856(SensorBase):

    def __init__(self, config):
        SensorBase.__init__(self, config, "MAX31856", self.build_spi_init(config))

    def handle_fault(self, adc, fault):
        if fault & MAX31856_FAULT_CJRANGE:
            self.report_fault("Max31856: Cold Junction Range Fault")
        if fault & MAX31856_FAULT_TCRANGE:
            self.report_fault("Max31856: Thermocouple Range Fault")
        if fault & MAX31856_FAULT_CJHIGH:
            self.report_fault("Max31856: Cold Junction High Fault")
        if fault & MAX31856_FAULT_CJLOW:
            self.report_fault("Max31856: Cold Junction Low Fault")
        if fault & MAX31856_FAULT_TCHIGH:
            self.report_fault("Max31856: Thermocouple High Fault")
        if fault & MAX31856_FAULT_TCLOW:
            self.report_fault("Max31856: Thermocouple Low Fault")
        if fault & MAX31856_FAULT_OVUV:
            self.report_fault("Max31856: Over/Under Voltage Fault")
        if fault & MAX31856_FAULT_OPEN:
            self.report_fault("Max31856: Thermocouple Open Fault")

    def calc_temp(self, adc):
        adc = adc >> MAX31856_SCALE
        if adc & 262144:
            adc = ((adc & 262143) + 1) * -1
        temp = MAX31856_MULT * adc
        return temp

    def calc_adc(self, temp):
        adc = int(temp / MAX31856_MULT + 0.5)
        adc = max(0, min(262143, adc)) << MAX31856_SCALE
        return adc

    def build_spi_init(self, config):
        cmds = []
        value = MAX31856_CR0_AUTOCONVERT
        if config.getboolean("tc_use_50Hz_filter", False):
            value |= MAX31856_CR0_FILT50HZ
        cmds.append(128 + MAX31856_CR0_REG)
        cmds.append(value)
        types = {
          'B': 0,
          'E': 1,
          'J': 2,
          'K': 3,
          'N': 4,
          'R': 5,
          'S': 6,
          'T': 7}
        value = config.getchoice("tc_type", types, default="K")
        averages = {
          1: MAX31856_CR1_AVGSEL1,
          2: MAX31856_CR1_AVGSEL2,
          4: MAX31856_CR1_AVGSEL4,
          8: MAX31856_CR1_AVGSEL8,
          16: MAX31856_CR1_AVGSEL16}
        value |= config.getchoice("tc_averaging_count", averages, 1)
        cmds.append(value)
        value = MAX31856_MASK_VOLTAGE_UNDER_OVER_FAULT | MAX31856_MASK_THERMOCOUPLE_OPEN_FAULT
        cmds.append(value)
        return cmds


MAX31855_SCALE = 18
MAX31855_MULT = 0.25

class MAX31855(SensorBase):

    def __init__(self, config):
        SensorBase.__init__(self, config, "MAX31855", spi_mode=0)

    def handle_fault(self, adc, fault):
        if fault & 1:
            self.report_fault("MAX31855 : Open Circuit")
        if fault & 2:
            self.report_fault("MAX31855 : Short to GND")
        if fault & 4:
            self.report_fault("MAX31855 : Short to Vcc")

    def calc_temp(self, adc):
        adc = adc >> MAX31855_SCALE
        if adc & 8192:
            adc = ((adc & 8191) + 1) * -1
        temp = MAX31855_MULT * adc
        return temp

    def calc_adc(self, temp):
        adc = int(temp / MAX31855_MULT + 0.5)
        adc = max(0, min(8191, adc)) << MAX31855_SCALE
        return adc


MAX6675_SCALE = 3
MAX6675_MULT = 0.25

class MAX6675(SensorBase):

    def __init__(self, config):
        SensorBase.__init__(self, config, "MAX6675", spi_mode=0)

    def handle_fault(self, adc, fault):
        if fault & 2:
            self.report_fault("Max6675 : Device ID error")
        if fault & 4:
            self.report_fault("Max6675 : Thermocouple Open Fault")

    def calc_temp(self, adc):
        adc = adc >> MAX6675_SCALE
        if adc & 8192:
            adc = ((adc & 8191) + 1) * -1
        temp = MAX6675_MULT * adc
        return temp

    def calc_adc(self, temp):
        adc = int(temp / MAX6675_MULT + 0.5)
        adc = max(0, min(8191, adc)) << MAX6675_SCALE
        return adc


MAX31865_CONFIG_REG = 0
MAX31865_RTDMSB_REG = 1
MAX31865_RTDLSB_REG = 2
MAX31865_HFAULTMSB_REG = 3
MAX31865_HFAULTLSB_REG = 4
MAX31865_LFAULTMSB_REG = 5
MAX31865_LFAULTLSB_REG = 6
MAX31865_FAULTSTAT_REG = 7
MAX31865_CONFIG_BIAS = 128
MAX31865_CONFIG_MODEAUTO = 64
MAX31865_CONFIG_1SHOT = 32
MAX31865_CONFIG_3WIRE = 16
MAX31865_CONFIG_FAULTCLEAR = 2
MAX31865_CONFIG_FILT50HZ = 1
MAX31865_FAULT_HIGHTHRESH = 128
MAX31865_FAULT_LOWTHRESH = 64
MAX31865_FAULT_REFINLOW = 32
MAX31865_FAULT_REFINHIGH = 16
MAX31865_FAULT_RTDINLOW = 8
MAX31865_FAULT_OVUV = 4
MAX31865_ADC_MAX = 32768
CVD_A = 0.0039083
CVD_B = -5.775e-07

class MAX31865(SensorBase):

    def __init__(self, config):
        rtd_nominal_r = config.getfloat("rtd_nominal_r", 100.0, above=0.0)
        rtd_reference_r = config.getfloat("rtd_reference_r", 430.0, above=0.0)
        adc_to_resist = rtd_reference_r / float(MAX31865_ADC_MAX)
        self.adc_to_resist_div_nominal = adc_to_resist / rtd_nominal_r
        self.config_reg = self.build_spi_init(config)
        SensorBase.__init__(self, config, "MAX31865", self.config_reg)

    def handle_fault(self, adc, fault):
        if fault & 128:
            self.report_fault("Max31865 RTD input is disconnected")
        if fault & 64:
            self.report_fault("Max31865 RTD input is shorted")
        if fault & 32:
            self.report_fault("Max31865 VREF- is greater than 0.85 * VBIAS, FORCE- open")
        if fault & 16:
            self.report_fault("Max31865 VREF- is less than 0.85 * VBIAS, FORCE- open")
        if fault & 8:
            self.report_fault("Max31865 VRTD- is less than 0.85 * VBIAS, FORCE- open")
        if fault & 4:
            self.report_fault("Max31865 Overvoltage or undervoltage fault")
        if not fault & 252:
            self.report_fault("Max31865 Unspecified error")
        self.spi.spi_send(self.config_reg)

    def calc_temp(self, adc):
        adc = adc >> 1
        R_div_nominal = adc * self.adc_to_resist_div_nominal
        discriminant = math.sqrt(CVD_A ** 2 - 4.0 * CVD_B * (1.0 - R_div_nominal))
        temp = (-CVD_A + discriminant) / (2.0 * CVD_B)
        return temp

    def calc_adc(self, temp):
        temp = min(temp, 1768.3)
        R_div_nominal = 1.0 + CVD_A * temp + CVD_B * temp * temp
        adc = int(R_div_nominal / self.adc_to_resist_div_nominal + 0.5)
        adc = max(0, min(MAX31865_ADC_MAX - 1, adc))
        adc = adc << 1
        return adc

    def build_spi_init(self, config):
        value = MAX31865_CONFIG_BIAS | MAX31865_CONFIG_MODEAUTO | MAX31865_CONFIG_FAULTCLEAR
        if config.getboolean("rtd_use_50Hz_filter", False):
            value |= MAX31865_CONFIG_FILT50HZ
        if config.getint("rtd_num_of_wires", 2) == 3:
            value |= MAX31865_CONFIG_3WIRE
        cmd = 128 + MAX31865_CONFIG_REG
        return [
         cmd, value]


Sensors = {
  'MAX6675': MAX6675,
  'MAX31855': MAX31855,
  'MAX31856': MAX31856,
  'MAX31865': MAX31865}

def load_config(config):
    pheaters = config.get_printer().load_object(config, "heaters")
    for (name, klass) in Sensors.items():
        pheaters.add_sensor_factory(name, klass)

